 if len(nums)<4 or not np.allclose(nums[1:4],[row.land_total_thousand_ha_2021,row.farmland_all_territory_thousand_ha_2021,row.arable_all_territory_thousand_ha_2021]):errors.append({'subject':name,'reason':'PDFcells_disagree','actual_first_numbers':nums[:4]})
